$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$root = (Get-Location).Path
if (-not (Test-Path (Join-Path $root 'pubspec.yaml'))) {
    throw 'Run this script from the almustafa-connect-erp project root.'
}

$utf8 = New-Object System.Text.UTF8Encoding($false)
$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$backupRoot = Join-Path (Split-Path $root -Parent) "almustafa-connect-erp_backups/academic_calendar_phase4_integration_$stamp"

function Read-ProjectFile {
    param([Parameter(Mandatory = $true)][string]$RelativePath)
    $path = Join-Path $root $RelativePath
    if (-not (Test-Path $path)) {
        throw "Required file not found: $RelativePath"
    }
    return [IO.File]::ReadAllText($path).Replace("`r`n", "`n")
}

function Write-ProjectFile {
    param(
        [Parameter(Mandatory = $true)][string]$RelativePath,
        [Parameter(Mandatory = $true)][string]$Content
    )
    $path = Join-Path $root $RelativePath
    New-Item -ItemType Directory -Path (Split-Path $path -Parent) -Force | Out-Null
    [IO.File]::WriteAllText($path, $Content, $utf8)
    Write-Host "Created/updated: $RelativePath" -ForegroundColor Green
}

function Backup-ProjectFile {
    param([Parameter(Mandatory = $true)][string]$RelativePath)
    $source = Join-Path $root $RelativePath
    if (-not (Test-Path $source)) { return }
    $destination = Join-Path $backupRoot $RelativePath
    New-Item -ItemType Directory -Path (Split-Path $destination -Parent) -Force | Out-Null
    Copy-Item $source $destination -Force
}

function Ensure-BeforeAnchor {
    param(
        [Parameter(Mandatory = $true)][string]$Content,
        [Parameter(Mandatory = $true)][string]$UniqueMarker,
        [Parameter(Mandatory = $true)][string]$Anchor,
        [Parameter(Mandatory = $true)][string]$Block
    )
    if ($Content.Contains($UniqueMarker)) { return $Content }
    $index = $Content.IndexOf($Anchor)
    if ($index -lt 0) { throw "Integration anchor not found: $Anchor" }
    return $Content.Substring(0, $index) + $Block + $Content.Substring($index)
}

$payloads = @{
    'lib/features/academic_calendar/domain/services/academic_calendar_policy_service.dart' = ''
    'lib/features/academic_calendar/data/services/academic_calendar_policy_service_impl.dart' = ''
    'lib/features/academic_calendar/presentation/pages/academic_calendar_integration_page.dart' = ''
}
$serviceLocator = 'lib/core/di/service_locator.dart'
$calendarPage = 'lib/features/academic_calendar/presentation/pages/academic_calendar_page.dart'
$feePage = 'lib/features/fees/presentation/pages/monthly_fee_generation_page.dart'

foreach ($relativePath in (@($serviceLocator, $calendarPage, $feePage) + $payloads.Keys)) {
    Backup-ProjectFile -RelativePath $relativePath
}

foreach ($item in $payloads.GetEnumerator()) {
    $text = [Text.Encoding]::UTF8.GetString(
        [Convert]::FromBase64String($item.Value)
    )
    Write-ProjectFile -RelativePath $item.Key -Content $text
}

# Service locator
$content = Read-ProjectFile -RelativePath $serviceLocator

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker 'academic_calendar_policy_service_impl.dart' `
    -Anchor "import '../../features/academic_calendar/data/repositories/academic_year_config_repository_impl.dart';" `
    -Block "import '../../features/academic_calendar/data/services/academic_calendar_policy_service_impl.dart';`n"

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker 'academic_calendar_policy_service.dart' `
    -Anchor "import '../../features/academic_calendar/domain/repositories/academic_year_config_repository.dart';" `
    -Block "import '../../features/academic_calendar/domain/services/academic_calendar_policy_service.dart';`n"

$serviceRegistration = @'
  sl.registerLazySingleton<AcademicCalendarPolicyService>(
    () => AcademicCalendarPolicyServiceImpl(
      sl<AcademicYearConfigRepository>(),
      sl<AcademicCalendarRepository>(),
    ),
  );

'@

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker 'registerLazySingleton<AcademicCalendarPolicyService>' `
    -Anchor '  sl.registerLazySingleton<AcademicYearConfigRepository>(' `
    -Block $serviceRegistration

Write-ProjectFile -RelativePath $serviceLocator -Content $content

# Calendar page integration button
$content = Read-ProjectFile -RelativePath $calendarPage

if (-not $content.Contains(
    "import 'academic_calendar_integration_page.dart';"
)) {
    $content = $content.Replace(
        "import 'academic_calendar_validation_page.dart';",
        "import 'academic_calendar_integration_page.dart';`nimport 'academic_calendar_validation_page.dart';"
    )
}

if (-not $content.Contains(
    'const AcademicCalendarIntegrationPage('
)) {
    $validationMarker = @'
          TextButton.icon(
            onPressed: () {
              Navigator.of(context).push<void>(
                MaterialPageRoute<void>(
                  builder: (_) => AcademicCalendarValidationPage(
                    academicSession: _sessionController.text.trim(),
                  ),
                ),
              );
            },
            icon: const Icon(Icons.fact_check_outlined),
            label: const Text('Validate'),
          ),
'@

    if (-not $content.Contains($validationMarker)) {
        throw 'Could not locate the Validate AppBar action.'
    }

    $integrationAction = @'
          TextButton.icon(
            onPressed: () {
              Navigator.of(context).push<void>(
                MaterialPageRoute<void>(
                  builder: (_) => AcademicCalendarIntegrationPage(
                    academicSession: _sessionController.text.trim(),
                  ),
                ),
              );
            },
            icon: const Icon(Icons.hub_outlined),
            label: const Text('Integrations'),
          ),
'@

    $content = $content.Replace(
        $validationMarker,
        $integrationAction + $validationMarker
    )
}

Write-ProjectFile -RelativePath $calendarPage -Content $content

# Fee Management integration: load configured due day.
$content = Read-ProjectFile -RelativePath $feePage

if (-not $content.Contains(
    "academic_calendar/domain/services/academic_calendar_policy_service.dart"
)) {
    $content = $content.Replace(
        "import '../../../../core/di/service_locator.dart';",
        "import '../../../../core/di/service_locator.dart';`nimport '../../../academic_calendar/domain/services/academic_calendar_policy_service.dart';"
    )
}

if (-not $content.Contains('_loadCalendarFeeDefaults')) {
    $initMarker = @'
  @override
  void initState() {
    super.initState();
    _loadAssignments();
  }
'@
    $replacement = @'
  @override
  void initState() {
    super.initState();
    _loadCalendarFeeDefaults();
    _loadAssignments();
  }

  Future<void> _loadCalendarFeeDefaults() async {
    try {
      final service = sl<AcademicCalendarPolicyService>();
      final config = await service.getConfig(
        _sessionController.text.trim(),
      );
      if (!mounted || config == null) return;
      setState(() {
        _dueDayController.text = '${config.feeDueDay}';
      });
    } catch (_) {
      // Keep the existing default when Academic Year Wizard is not ready.
    }
  }
'@

    if (-not $content.Contains($initMarker)) {
        throw 'Monthly Fee Generation initState anchor not found.'
    }
    $content = $content.Replace($initMarker, $replacement)
}

Write-ProjectFile -RelativePath $feePage -Content $content

$formatFiles = @($serviceLocator, $calendarPage, $feePage) + $payloads.Keys

Write-Host ''
Write-Host 'Running dart format...' -ForegroundColor Cyan
& dart format $formatFiles
if ($LASTEXITCODE -ne 0) {
    throw 'dart format failed.'
}

Write-Host ''
Write-Host 'Running flutter analyze...' -ForegroundColor Cyan
& flutter analyze
if ($LASTEXITCODE -ne 0) {
    throw 'flutter analyze found issues. Copy the complete output into ChatGPT.'
}

Write-Host ''
Write-Host 'Academic Calendar Phase 4 ERP Integration completed successfully.' -ForegroundColor Green
Write-Host 'Academic Calendar is ready to freeze after final QA.' -ForegroundColor Cyan
Write-Host "Backup: $backupRoot" -ForegroundColor DarkGray
